CREATE UNIQUE INDEX "PerfOptCoinPerformance_performanceKey_key" ON "PerfOptCoinPerformance"("performanceKey");
CREATE UNIQUE INDEX "PerfOptRecommendation_recommendationKey_key" ON "PerfOptRecommendation"("recommendationKey");
