CREATE UNIQUE INDEX "PerfOptTimeline_timelineKey_key" ON "PerfOptTimeline"("timelineKey");
CREATE UNIQUE INDEX "PerfOptSuccessMetrics_metricsKey_key" ON "PerfOptSuccessMetrics"("metricsKey");
